"""v0.1.1: shipped CPU installs get the 11 MB onnxruntime wheel instead of
onnxruntime-gpu (280 MB) — scripts/export_requirements.py does the swap."""
from __future__ import annotations

import re
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))

import export_requirements as er  # noqa: E402

SAMPLE = """\
# This file was autogenerated by uv
coloredlogs==15.0.1 \\
    --hash=sha256:aaaa
    # via
    #   onnxruntime
    #   onnxruntime-gpu
onnxruntime==1.20.0 ; platform_machine == 'aarch64' or sys_platform == 'darwin' \\
    --hash=sha256:{h1} \\
    --hash=sha256:{h2}
    # via sound-system
onnxruntime-gpu==1.20.0 ; platform_machine != 'aarch64' and sys_platform != 'darwin' \\
    --hash=sha256:cccc
    # via sound-system
torch==2.5.1+cpu \\
    --hash=sha256:dddd
"""


def _lock_hashes() -> list[str]:
    return sorted(er._locked_ort_hashes(ROOT / "uv.lock"))


def test_swap_drops_gpu_and_unconditions_cpu():
    h = _lock_hashes()
    assert len(h) == 2  # win_amd64 + manylinux x86_64, cp311
    out = er.cpu_onnxruntime_swap(SAMPLE.format(h1=h[0], h2=h[1]))
    reqs = [l for l in out.splitlines() if l and not l[0].isspace()
            and not l.startswith("#")]
    assert "onnxruntime==1.20.0 \\" in reqs
    assert not any(l.startswith("onnxruntime-gpu") for l in reqs)
    assert any(l.startswith("torch==") for l in reqs)  # others untouched
    assert "--hash=sha256:cccc" not in out


def test_swap_refuses_when_x64_hashes_missing():
    with pytest.raises(SystemExit):
        er.cpu_onnxruntime_swap(SAMPLE.format(h1="1111", h2="2222"))


def test_swap_refuses_unexpected_shape():
    with pytest.raises(SystemExit):
        er.cpu_onnxruntime_swap("torch==2.5.1 \\\n    --hash=sha256:dd\n")


@pytest.mark.parametrize("hashes", [True, False])
def test_real_cpu_export_has_one_plain_ort(tmp_path, hashes):
    out = er.export("cpu", tmp_path / "r.txt", hashes=hashes).read_text("utf-8")
    reqs = [l for l in out.splitlines() if l and not l[0].isspace()
            and not l.startswith("#")]
    ort = [l for l in reqs if re.match(r"onnxruntime(-gpu)?==", l)]
    assert ort == ["onnxruntime==1.20.0" + (" \\" if hashes else "")]
    if hashes:
        for h in _lock_hashes():
            assert f"sha256:{h}" in out


def test_real_cu124_export_untouched(tmp_path):
    out = er.export("cu124", tmp_path / "r.txt").read_text("utf-8")
    assert re.search(r"^onnxruntime-gpu==1\.20\.0 ;", out, re.M)


def test_every_packager_uses_the_helper():
    for f in ("scripts/build-installer.ps1", "scripts/package.ps1",
              "scripts/package-unix.sh", "scripts/build-wheel.py"):
        s = (ROOT / f).read_text("utf-8")
        assert "export_requirements" in s, f
        assert "uv export --frozen" not in s, f"{f} calls uv export directly"
        assert '"uv", "export"' not in s, f"{f} calls uv export directly"


def test_requirement_installs_ignore_project_config():
    """`uv pip install` run next to pyproject.toml applies its [tool.uv]
    override, which DROPS plain onnxruntime on Windows/Linux x64 — a cpu
    install would end up with no ONNX Runtime at all. Every install from
    an exported requirements file must pass --no-config."""
    sites = {
        "scripts/install-runtime.ps1": "$uvArgs = @(",
        "scripts/package.ps1": '"pip", "install",',
        "scripts/package-unix.sh": "\nuv pip install",  # the real call, not comments
        "install.sh": '"$UVBIN" pip install',
        "packaging/pypi/safa_bootstrap/cli.py": '[uv, "pip", "install"',
    }
    for f, anchor in sites.items():
        s = (ROOT / f).read_text("utf-8-sig")
        i = s.index(anchor)
        window = s[i:i + 400]
        assert "--no-config" in window, f"{f}: uv pip install without --no-config"
        # the export is the full locked closure: re-resolving fails on
        # cu124 (faster-whisper wants `onnxruntime`, the lock ships -gpu)
        assert "--no-deps" in window, f"{f}: uv pip install without --no-deps"
